/**
 * Name validation for reverse search.
 *
 * Validates whether a name could be generated by the nms_namegen algorithms.
 * Used to skip impossible candidates before expensive reverse search.
 *
 * Validation approach:
 * 1. Character set: only lowercase letters (a-z) for base names
 * 2. First letter: always uppercase in output
 * 3. Structure: hyphenation, roman numerals, adornments
 * 4. Pattern: vowel/consonant rules from generateName
 */

// ─── Constants ────────────────────────────────────────────────────────

const VOWELS = "aeiou";
const CONSONANTS = "bcdfghjklmnpqrstvwxyz";

const ROMAN_NUMERALS = [
  "I", "II", "III", "IV", "V", "VI", "VII",
  "VIII", "IX", "X", "XI", "XII", "XIII", "XIV", "XV", "XVI",
  "XVII", "XVIII", "XIX", "XX",
];

const REGION_ADORNMENTS = [
  "Sea of",
  "Clouds of",
  "Gap of",
  "Sea of",
  "Anomaly of",
  "Expanse of",
  "Trio of",
  "Void of",
  "Heaven of",
  "Oceans of",
  "Beyond",
];

const PLANET_ADORNMENTS = [
  "Prime",
  "Major",
  "Minor",
  "Alpha",
  "Beta",
  "Gamma",
  "Delta",
  "Omega",
  "Sigma",
  "Tau",
];

const PLANET_STYLES = [
  "%PROCNORM%",
  "%PROCNORM% %ADORNMENT%",
  "%PROCNORM% %NUMERAL%",
  "%PROCNORM% %SHORTCODE%",
  "%PROCLONG% %PROCSHORT%",
  "%PROCSHORT% %LONGCODE%",
  "%PROCNORM%",
  "%PROCNORM% %ADORNMENT%",
  "%PROCNORM% %NUMERAL%",
  "Style 9",
  "New %PROCNORM%",
];

// ─── Validation Result ────────────────────────────────────────────────

export interface ValidationResult {
  valid: boolean;
  reason?: string;
}

// ─── System Name Validation ───────────────────────────────────────────

/**
 * Validate a system name against generation rules.
 *
 * Rules:
 * 1. Must start with uppercase letter (A-Z)
 * 2. Rest must be lowercase letters (a-z) or hyphen
 * 3. If hyphenated: exactly one hyphen, both parts valid
 * 4. If has Roman numeral: must be I-XX after the base name
 * 5. Base name length: 2-63 characters
 * 6. Characters must follow generateName patterns (no impossible combos)
 */
export function isValidSystemName(name: string): ValidationResult {
  if (!name || name.length === 0) {
    return { valid: false, reason: "Empty name" };
  }

  // Check first character is uppercase letter
  if (!/^[A-Z]/.test(name)) {
    return { valid: false, reason: "Must start with uppercase letter" };
  }

  // Check for Roman numeral suffix
  let baseName = name;
  let hasNumeral = false;

  for (const numeral of ROMAN_NUMERALS) {
    if (name.endsWith(" " + numeral)) {
      baseName = name.slice(0, -(numeral.length + 1));
      hasNumeral = true;
      break;
    }
  }

  // Validate base name structure
  const baseResult = validateSystemBaseName(baseName);
  if (!baseResult.valid) return baseResult;

  return { valid: true };
}

function validateSystemBaseName(name: string): ValidationResult {
  // Check for hyphen
  const hyphenIdx = name.indexOf("-");

  if (hyphenIdx !== -1) {
    // Hyphenated name: exactly one hyphen
    if (name.indexOf("-", hyphenIdx + 1) !== -1) {
      return { valid: false, reason: "Multiple hyphens not allowed" };
    }

    const part1 = name.slice(0, hyphenIdx);
    const part2 = name.slice(hyphenIdx + 1);

    if (part1.length < 1 || part2.length < 1) {
      return { valid: false, reason: "Hyphen parts cannot be empty" };
    }

    // Both parts must be valid lowercase (except first char of part1 is uppercase)
    const part1Lower = part1.charAt(0).toLowerCase() + part1.slice(1);
    const result1 = validateLowercaseName(part1Lower);
    if (!result1.valid) return result1;

    // Part2 first letter is uppercase
    const part2Lower = part2.charAt(0).toLowerCase() + part2.slice(1);
    const result2 = validateLowercaseName(part2Lower);
    if (!result2.valid) return result2;

    return { valid: true };
  }

  // Non-hyphenated: validate as single lowercase name (first char already uppercase)
  const lower = name.charAt(0).toLowerCase() + name.slice(1);
  return validateLowercaseName(lower);
}

function validateLowercaseName(name: string): ValidationResult {
  if (name.length < 1) {
    return { valid: false, reason: "Name too short" };
  }

  if (name.length > 63) {
    return { valid: false, reason: "Name too long (max 63)" };
  }

  // Check all characters are lowercase letters
  if (!/^[a-z]+$/.test(name)) {
    return { valid: false, reason: "Invalid characters (only a-z allowed)" };
  }

  // Check for impossible consonant sequences
  // generateName inserts vowels to avoid 4+ consecutive consonants
  const consonantRun = getConsecutiveConsonants(name);
  if (consonantRun !== -1) {
    return {
      valid: false,
      reason: `Impossible consonant sequence at position ${consonantRun}`,
    };
  }

  return { valid: true };
}

/**
 * Count consecutive consonants that would trigger vowel insertion.
 * Returns index of impossible sequence, or -1 if valid.
 */
function getConsecutiveConsonants(name: string): number {
  let consonance = 0;
  for (let i = 0; i < name.length; i++) {
    if (consonance < 3) {
      if (CONSONANTS.includes(name[i]!)) consonance++;
      else consonance = 0;
    } else {
      // At 4 consecutive consonants, check if vowel insertion would occur
      // The algorithm inserts vowels to prevent this
      if (!VOWELS.includes(name[i]!) && !"y".includes(name[i]!)) {
        return i - 3;
      } else {
        consonance = 0;
      }
    }
  }
  return -1;
}

// ─── Region Name Validation ───────────────────────────────────────────

/**
 * Validate a region name against generation rules.
 *
 * Rules:
 * 1. May start with an adornment (e.g., "Sea of", "Clouds of")
 * 2. Base name follows system name rules (lowercase + capitalize first)
 * 3. Adornment words are always capitalized
 */
export function isValidRegionName(name: string): ValidationResult {
  if (!name || name.length === 0) {
    return { valid: false, reason: "Empty name" };
  }

  // Check if starts with known adornment
  for (const adornment of REGION_ADORNMENTS) {
    if (name.startsWith(adornment + " ")) {
      const baseName = name.slice(adornment.length + 1);
      return validateRegionBaseName(baseName);
    }
  }

  // No adornment: validate as base name
  return validateRegionBaseName(name);
}

function validateRegionBaseName(name: string): ValidationResult {
  if (!name || name.length === 0) {
    return { valid: false, reason: "Empty base name" };
  }

  // Must start with uppercase
  if (!/^[A-Z]/.test(name)) {
    return { valid: false, reason: "Base name must start with uppercase" };
  }

  // Rest must be lowercase letters, allowing spaces between words
  if (!/^[A-Z][a-z]+( [A-Z][a-z]+)*$/.test(name)) {
    return { valid: false, reason: "Invalid characters in base name" };
  }

  // Check length
  if (name.length > 63) {
    return { valid: false, reason: "Base name too long" };
  }

  // Check consonant sequences
  const lower = name.charAt(0).toLowerCase() + name.slice(1);
  const consonantRun = getConsecutiveConsonants(lower);
  if (consonantRun !== -1) {
    return {
      valid: false,
      reason: `Impossible consonant sequence at position ${consonantRun}`,
    };
  }

  return { valid: true };
}

// ─── Planet Name Validation ───────────────────────────────────────────

/**
 * Validate a planet name against generation rules.
 *
 * Rules:
 * 1. Must match one of the 11 style templates
 * 2. Components: procnorm (4-8), procshort (4-5), proclong (6-10)
 * 3. Adornments: Prime, Major, Minor, Alpha, Beta, Gamma, Delta, Omega, Sigma, Tau
 * 4. Roman numerals: I-XX
 * 5. Shortcode: letter (A-Z) + number (0-79)
 * 6. Longcode: number (11-99) + "/" + letter (A-Z) + digit (1-9)
 */
export function isValidPlanetName(name: string): ValidationResult {
  if (!name || name.length === 0) {
    return { valid: false, reason: "Empty name" };
  }

  // Check each style template
  for (const style of PLANET_STYLES) {
    const result = matchPlanetStyle(name, style);
    if (result.valid) return result;
  }

  return { valid: false, reason: "Does not match any planet name style" };
}

function matchPlanetStyle(name: string, style: string): ValidationResult {
  // Special case: "Style 9"
  if (style === "Style 9") {
    return { valid: false, reason: "Style 9 is not a valid template" };
  }

  // Handle "New %PROCNORM%" prefix
  if (style.startsWith("New ")) {
    if (!name.startsWith("New ")) {
      return { valid: false, reason: "Expected 'New ' prefix" };
    }
    const rest = name.slice(4);
    const result = validateProcnorm(rest);
    if (result.valid) return result;
    return { valid: false, reason: "Invalid procnorm after 'New '" };
  }

  // Parse template into parts (preserving spaces as separators)
  const parts = style.split(" ");

  // Try to match name against template parts
  return matchParts(name, parts, 0);
}

function matchParts(name: string, parts: string[], startIdx: number): ValidationResult {
  if (parts.length === 0) {
    return startIdx === name.length
      ? { valid: true }
      : { valid: false, reason: "Extra characters after template" };
  }

  const part = parts[0]!;
  const remaining = parts.slice(1);

  // Skip spaces in the name between parts
  let currentIdx = startIdx;
  while (currentIdx < name.length && name[currentIdx] === " ") {
    currentIdx++;
  }

  if (part === "%PROCNORM%") {
    // Match 4-8 lowercase letters (first char uppercase in output)
    for (let len = 4; len <= 8; len++) {
      if (currentIdx + len > name.length) break;

      const segment = name.slice(currentIdx, currentIdx + len);
      const result = validateProcnorm(segment);
      if (result.valid) {
        const next = matchParts(name, remaining, currentIdx + len);
        if (next.valid) return next;
      }
    }
    return { valid: false, reason: "Invalid procnorm segment" };
  }

  if (part === "%PROCSHORT%") {
    // Match 4-5 lowercase letters
    for (let len = 4; len <= 5; len++) {
      if (currentIdx + len > name.length) break;

      const segment = name.slice(currentIdx, currentIdx + len);
      const result = validateProcshort(segment);
      if (result.valid) {
        const next = matchParts(name, remaining, currentIdx + len);
        if (next.valid) return next;
      }
    }
    return { valid: false, reason: "Invalid procshort segment" };
  }

  if (part === "%PROCLONG%") {
    // Match 6-10 lowercase letters
    for (let len = 6; len <= 10; len++) {
      if (currentIdx + len > name.length) break;

      const segment = name.slice(currentIdx, currentIdx + len);
      const result = validateProclong(segment);
      if (result.valid) {
        const next = matchParts(name, remaining, currentIdx + len);
        if (next.valid) return next;
      }
    }
    return { valid: false, reason: "Invalid proclong segment" };
  }

  if (part === "%ADORNMENT%") {
    // Match planet adornment
    for (const adj of PLANET_ADORNMENTS) {
      if (name.startsWith(adj, currentIdx)) {
        const next = matchParts(name, remaining, currentIdx + adj.length);
        if (next.valid) return next;
      }
    }
    return { valid: false, reason: "Invalid planet adornment" };
  }

  if (part === "%NUMERAL%") {
    // Match Roman numeral
    for (const numeral of ROMAN_NUMERALS) {
      if (name.startsWith(numeral, currentIdx)) {
        const next = matchParts(name, remaining, currentIdx + numeral.length);
        if (next.valid) return next;
      }
    }
    return { valid: false, reason: "Invalid Roman numeral" };
  }

  if (part === "%SHORTCODE%") {
    // Match letter (A-Z) + number (0-79)
    if (currentIdx + 1 >= name.length) {
      return { valid: false, reason: "Shortcode too short" };
    }
    const letter = name[currentIdx]!;
    const numStr = name.slice(currentIdx + 1);
    const numMatch = numStr.match(/^(\d{1,2})/);

    if (!letter.match(/^[A-Z]/) || !numMatch) {
      return { valid: false, reason: "Invalid shortcode format" };
    }

    const num = parseInt(numMatch[1]!, 10);
    if (num >= 80) {
      return { valid: false, reason: "Shortcode number must be < 80" };
    }

    const next = matchParts(name, remaining, currentIdx + 1 + numMatch[1]!.length);
    if (next.valid) return next;
    return { valid: false, reason: "Invalid shortcode" };
  }

  if (part === "%LONGCODE%") {
    // Match number (11-99) + "/" + letter (A-Z) + digit (1-9)
    const longcodeMatch = name.slice(currentIdx).match(/^(\d{2})\/([A-Z])(\d)/);
    if (!longcodeMatch) {
      return { valid: false, reason: "Invalid longcode format" };
    }

    const num = parseInt(longcodeMatch[1]!, 10);
    if (num < 11 || num > 99) {
      return { valid: false, reason: "Longcode number must be 11-99" };
    }

    const digit = parseInt(longcodeMatch[3]!, 10);
    if (digit < 1 || digit > 9) {
      return { valid: false, reason: "Longcode digit must be 1-9" };
    }

    const next = matchParts(name, remaining, currentIdx + longcodeMatch[0]!.length);
    if (next.valid) return next;
    return { valid: false, reason: "Invalid longcode" };
  }

  // Literal text (like "New")
  if (name.startsWith(part, currentIdx)) {
    return matchParts(name, remaining, currentIdx + part.length);
  }

  return { valid: false, reason: `Expected "${part}" at position ${currentIdx}` };
}

function validateProcnorm(name: string): ValidationResult {
  // First letter uppercase, rest lowercase, length 4-8
  if (name.length < 4 || name.length > 8) {
    return { valid: false, reason: "Procnorm length must be 4-8" };
  }

  if (!/^[A-Z][a-z]+$/.test(name)) {
    return { valid: false, reason: "Invalid procnorm characters" };
  }

  const lower = name.charAt(0).toLowerCase() + name.slice(1);
  const consonantRun = getConsecutiveConsonants(lower);
  if (consonantRun !== -1) {
    return { valid: false, reason: "Impossible consonant sequence in procnorm" };
  }

  return { valid: true };
}

function validateProcshort(name: string): ValidationResult {
  if (name.length < 4 || name.length > 5) {
    return { valid: false, reason: "Procshort length must be 4-5" };
  }

  if (!/^[A-Z][a-z]+$/.test(name)) {
    return { valid: false, reason: "Invalid procshort characters" };
  }

  const lower = name.charAt(0).toLowerCase() + name.slice(1);
  const consonantRun = getConsecutiveConsonants(lower);
  if (consonantRun !== -1) {
    return { valid: false, reason: "Impossible consonant sequence in procshort" };
  }

  return { valid: true };
}

function validateProclong(name: string): ValidationResult {
  if (name.length < 6 || name.length > 10) {
    return { valid: false, reason: "Proclong length must be 6-10" };
  }

  if (!/^[A-Z][a-z]+$/.test(name)) {
    return { valid: false, reason: "Invalid proclong characters" };
  }

  const lower = name.charAt(0).toLowerCase() + name.slice(1);
  const consonantRun = getConsecutiveConsonants(lower);
  if (consonantRun !== -1) {
    return { valid: false, reason: "Impossible consonant sequence in proclong" };
  }

  return { valid: true };
}
